/* ================= أدوات التاريخ والوقت ================= */

const pad = (n) => String(n).padStart(2, '0');

const dateToKey = (date) =>
  `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;

const keyToDate = (key) => {
  const [year, month, dayNumber] = key.split('-').map(Number);
  return new Date(year, month - 1, dayNumber);
};

const getFutureDates = () => {
  const result = [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let i = 0; i < BOOKING_DAYS_AHEAD; i++) {
    const date = new Date(today);
    date.setDate(today.getDate() + i);
    result.push(date);
  }
  return result;
};

const timeToMinutes = (value) => {
  const [hour, minute] = value.split(':').map(Number);
  return hour * 60 + minute;
};

const minutesToTime = (minutes) =>
  `${pad(Math.floor(minutes / 60))}:${pad(minutes % 60)}`;

/* ================= التطبيق ================= */

export default function App() {
  const [lang, setLang] = useState('en');
  const [selectedService, setSelectedService] = useState(null);
  const [showLangMenu, setShowLangMenu] = useState(false);
  const [screen, setScreen] = useState('home');
  const [selectedDateKey, setSelectedDateKey] = useState(null);
  const [time, setTime] = useState(null);
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [bookedSlots, setBookedSlots] = useState([]);
  const [holidayDates, setHolidayDates] = useState([]);
  const [galleryPhotos, setGalleryPhotos] = useState([]);
  const [adminPassword, setAdminPassword] = useState('');

  const t = translations[lang];
  const locale = locales[lang];

  const futureDates = useMemo(() => getFutureDates(), []);

  /* ---------- الشهر المتغير تلقائياً أثناء تمرير الأيام ---------- */

  const ITEM_W = 78; // عرض اليوم (70) + المسافة (8)
  const daysWidthRef = useRef(300);
  const [bookingRange, setBookingRange] = useState({ s: 0, e: 3 });
  const [adminRange, setAdminRange] = useState({ s: 0, e: 3 });

  const rangeFromOffset = (x) => {
    const last = futureDates.length - 1;
    const s = Math.max(0, Math.min(last, Math.floor(x / ITEM_W)));
    const e = Math.max(
      s,
      Math.min(last, Math.floor((x + daysWidthRef.current - 1) / ITEM_W))
    );
    return { s, e };
  };

  const makeScrollHandler = (setRange) => (ev) => {
    const { s, e } = rangeFromOffset(ev.nativeEvent.contentOffset.x);
    setRange((prev) => (prev.s === s && prev.e === e ? prev : { s, e }));
  };

  const makeLayoutHandler = (setRange) => (ev) => {
    daysWidthRef.current = ev.nativeEvent.layout.width;
    setRange(rangeFromOffset(0));
  };

  const getMonthName = (date) =>
    date.toLocaleDateString(locale, { month: 'long', year: 'numeric' });

  const getShortDayName = (date) =>
    date.toLocaleDateString(locale, { weekday: 'short' });

  /* اسم الشهر حسب الأيام الظاهرة: أكتوبر، أو أكتوبر / نوفمبر، أو نوفمبر */
  const getMonthLabel = ({ s, e }) => {
    const seen = [];
    for (let i = s; i <= e; i++) {
      const d = futureDates[i];
      if (!d) continue;
      const k = `${d.getFullYear()}-${d.getMonth()}`;
      if (!seen.some((x) => x.k === k)) seen.push({ k, d });
    }
    if (seen.length === 0) return '';
    if (seen.length === 1) return getMonthName(seen[0].d);
    const sameYear =
      seen[0].d.getFullYear() === seen[seen.length - 1].d.getFullYear();
    return seen
      .map((x, i) =>
        x.d.toLocaleDateString(
          locale,
          sameYear && i < seen.length - 1
            ? { month: 'long' }
            : { month: 'long', year: 'numeric' }
        )
      )
      .join(' / ');
  };

  /* اسم اليوم للحجوزات القديمة (0 = الأحد) */
  const weekdayName = (dayIndex) =>
    new Date(2024, 0, 7 + Number(dayIndex || 0)).toLocaleDateString(locale, {
      weekday: 'long',
    });

  /* ---------- تحميل البيانات ---------- */

  useEffect(() => {
    const loadData = async () => {
      try {
        const savedBookings = await AsyncStorage.getItem('barber_bookings');
        if (savedBookings) {
          const parsed = JSON.parse(savedBookings);
          if (Array.isArray(parsed)) setBookedSlots(parsed);
        }

        const savedHolidays = await AsyncStorage.getItem('barber_holidays');
        if (savedHolidays) {
          const parsed = JSON.parse(savedHolidays);
          if (Array.isArray(parsed)) setHolidayDates(parsed);
        }

        const savedPhotos = await AsyncStorage.getItem('barber_gallery');

        let list = [];
        if (savedPhotos) {
          const parsed = JSON.parse(savedPhotos);
          if (Array.isArray(parsed)) list = parsed;
        }

        /* نضيف صور أعمالك المدمجة مرة واحدة فقط لكل صورة */
        let seededIds = [];
        const seededRaw = await AsyncStorage.getItem('barber_gallery_seeded_ids');
        if (seededRaw) {
          const parsedIds = JSON.parse(seededRaw);
          if (Array.isArray(parsedIds)) seededIds = parsedIds;
        } else if (await AsyncStorage.getItem('barber_gallery_seeded')) {
          /* نسخة سابقة أضافت أول 3 صور */
          seededIds = ['work-1', 'work-2', 'work-3'];
        }

        const fresh = DEFAULT_PHOTOS.filter((p) => !seededIds.includes(p.id));
        if (fresh.length > 0) {
          list = [...list, ...fresh];
          await AsyncStorage.setItem('barber_gallery', JSON.stringify(list));
          await AsyncStorage.setItem(
            'barber_gallery_seeded_ids',
            JSON.stringify([...seededIds, ...fresh.map((p) => p.id)])
          );
        }

        setGalleryPhotos(list);
      } catch (error) {
        console.log('Error loading data:', error);
      }
    };
    loadData();
  }, []);

  /* ---------- الحفظ ---------- */

  const saveBookings = async (list) => {
    try {
      await AsyncStorage.setItem('barber_bookings', JSON.stringify(list));
    } catch (error) {
      console.log('Error saving bookings:', error);
    }
  };

  const saveHolidays = async (list) => {
    try {
      await AsyncStorage.setItem('barber_holidays', JSON.stringify(list));
    } catch (error) {
      console.log('Error saving holidays:', error);
    }
  };

  const saveGallery = async (list) => {
    try {
      await AsyncStorage.setItem('barber_gallery', JSON.stringify(list));
    } catch (error) {
      console.log('Error saving gallery:', error);
    }
  };

  /* ---------- العطلات ---------- */

  const isHoliday = (dateKey) => holidayDates.includes(dateKey);

  const toggleHoliday = (dateKey) => {
    const updated = holidayDates.includes(dateKey)
      ? holidayDates.filter((item) => item !== dateKey)
      : [...holidayDates, dateKey];
    setHolidayDates(updated);
    saveHolidays(updated);
  };

  /* ---------- الصور ---------- */

  const pickImage = async () => {
    let ImagePicker;
    try {
      ImagePicker = require('expo-image-picker');
    } catch (error) {
      Alert.alert(
        '!',
        'expo-image-picker غير مثبتة / is not installed. Add it in Snack: Add dependency.'
      );
      return null;
    }

    try {
      const perm = await ImagePicker.requestMediaLibraryPermissionsAsync();
      if (!perm.granted) {
        Alert.alert('!', t.gPerm);
        return null;
      }
      const res = await ImagePicker.launchImageLibraryAsync({ quality: 0.7 });
      if (res.canceled) return null;
      return res.assets[0].uri;
    } catch (error) {
      console.log('Error picking image:', error);
      return null;
    }
  };

  const addPhoto = async () => {
    const uri = await pickImage();
    if (!uri) return;
    const updated = [...galleryPhotos, { id: `${Date.now()}`, uri }];
    setGalleryPhotos(updated);
    saveGallery(updated);
  };

  const replacePhoto = async (id) => {
    const uri = await pickImage();
    if (!uri) return;
    const updated = galleryPhotos.map((p) => (p.id === id ? { ...p, uri } : p));
    setGalleryPhotos(updated);
    saveGallery(updated);
  };

  const deletePhoto = (id) => {
    Alert.alert(t.deleteTitle, t.deleteMessage, [
      { text: t.cancel, style: 'cancel' },
      {
        text: t.yesDelete,
        style: 'destructive',
        onPress: () => {
          const updated = galleryPhotos.filter((p) => p.id !== id);
          setGalleryPhotos(updated);
          saveGallery(updated);
        },
      },
    ]);
  };

  /* ---------- تعارض الحجوزات ---------- */

  const doesBookingOverlap = (startTime, duration, selectedDate, bookings = bookedSlots) => {
    const newStart = timeToMinutes(startTime);
    const newEnd = newStart + Number(duration);

    return bookings.some((booking) => {
      if (booking.dateKey && booking.dateKey !== selectedDate) return false;

      if (!booking.dateKey && booking.day !== keyToDate(selectedDate).getDay()) {
        return false;
      }

      const existingStart = timeToMinutes(booking.startTime);
      const existingEnd = existingStart + Number(booking.duration);

      return newStart < existingEnd && newEnd > existingStart;
    });
  };

  /* ---------- الأوقات المتاحة ---------- */

  const generateAvailableTimes = () => {
    if (!selectedDateKey || !selectedService) return [];
    if (isHoliday(selectedDateKey)) return [];

    const opening = timeToMinutes(OPENING_TIME);
    const closing = timeToMinutes(CLOSING_TIME);
    const serviceDuration = Number(selectedService.duration);
    const available = [];

    for (let start = opening; start + serviceDuration <= closing; start += 5) {
      const candidate = minutesToTime(start);
      if (!doesBookingOverlap(candidate, serviceDuration, selectedDateKey)) {
        available.push(candidate);
      }
    }

    return available.sort((a, b) => timeToMinutes(a) - timeToMinutes(b));
  };

  const availableTimes = generateAvailableTimes();

  /* ---------- تأكيد الحجز ---------- */

  const handleFinalBooking = () => {
    if (!name.trim() || !phone.trim() || !selectedDateKey || !time || !selectedService) {
      Alert.alert('!', t.errF);
      return;
    }

    if (isHoliday(selectedDateKey)) {
      Alert.alert('!', t.holidayNoBooking);
      setTime(null);
      return;
    }

    if (doesBookingOverlap(time, selectedService.duration, selectedDateKey)) {
      Alert.alert('!', t.timeTaken);
      setTime(null);
      return;
    }

    const selectedDate = keyToDate(selectedDateKey);

    const newBooking = {
      id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      clientName: name.trim(),
      clientPhone: phone.trim(),
      serviceName: selectedService.name,
      serviceId: selectedService.id,
      dateKey: selectedDateKey,
      day: selectedDate.getDay(),
      startTime: time,
      duration: selectedService.duration,
      createdAt: new Date().toISOString(),
    };

    const updatedSlots = [...bookedSlots, newBooking];
    setBookedSlots(updatedSlots);
    saveBookings(updatedSlots);

    const displayedDate = selectedDate.toLocaleDateString(locale, {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
    });

    Alert.alert(
      t.alertTitle,
      t.alertSuccess(name.trim(), selectedService.name, displayedDate, time),
      [
        {
          text: t.btnOk,
          onPress: () => {
            setName('');
            setPhone('');
            setSelectedDateKey(null);
            setTime(null);
            setSelectedService(null);
            setScreen('home');
          },
        },
      ]
    );
  };

  /* ---------- دخول الإدارة ---------- */

  const handleAdminLogin = () => {
    if (adminPassword === CORRECT_PASSWORD) {
      setAdminPassword('');
      setScreen('admin_dashboard');
    } else {
      Alert.alert('!', t.wrongPassword);
    }
  };

  /* ---------- حذف حجز ---------- */

  const deleteBooking = (id) => {
    Alert.alert(t.deleteBookingTitle, t.deleteBookingMessage, [
      { text: t.cancel, style: 'cancel' },
      {
        text: t.yesDelete,
        style: 'destructive',
        onPress: () => {
          const filtered = bookedSlots.filter((item) => item.id !== id);
          setBookedSlots(filtered);
          saveBookings(filtered);
        },
      },
    ]);
  };

  const resetBooking = () => {
    setName('');
    setPhone('');
    setSelectedDateKey(null);
    setTime(null);
    setSelectedService(null);
  };

  const formatAdminDate = (dateKey) => {
    if (!dateKey) return '';
    return keyToDate(dateKey).toLocaleDateString(locale, {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      year: 'numeric',
    });
  };

  /* ================= الواجهة ================= */

  return (
    <ScrollView
      style={styles.container}
      contentContainerStyle={styles.content}
      keyboardShouldPersistTaps="handled"
    >
      {/* HEADER */}

      <View style={styles.header}>
        <View style={{ flex: 1 }}>
          <Text style={styles.logo}>{t.logo}</Text>
          <Text style={styles.subtitle}>{t.sub}</Text>
        </View>

        <TouchableOpacity
          style={styles.adminTrigger}
          onPress={() => {
            setShowLangMenu(false);
            setScreen('admin_login');
          }}
        >
          <Text style={styles.adminTriggerText}>⚙️</Text>
        </TouchableOpacity>
      </View>

      {/* ============ HOME ============ */}

      {screen === 'home' && (
        <View style={styles.card}>
          <TouchableOpacity
            style={styles.langBox}
            onPress={() => setShowLangMenu(!showLangMenu)}
          >
            <Text style={styles.grayText}>{t.label}</Text>
            <Text style={styles.goldBold}>{langNames[lang]} ▾</Text>
          </TouchableOpacity>

          {showLangMenu && (
            <View style={styles.languageMenu}>
              {Object.keys(langNames).map((key) => (
                <TouchableOpacity
                  key={key}
                  style={styles.languageItem}
                  onPress={() => {
                    setLang(key);
                    setShowLangMenu(false);
                  }}
                >
                  <Text style={styles.whiteText}>{langNames[key]}</Text>
                </TouchableOpacity>
              ))}
            </View>
          )}

          <HeroImage />

          <Text style={styles.barberName}>Fayssal Barber</Text>
          <Text style={styles.location}>{t.loc}</Text>

          <View style={styles.line} />

          <Text style={styles.sectionTitle}>{t.title}</Text>

          {t.s.map((service) => (
            <TouchableOpacity
              key={service.id}
              style={[
                styles.item,
                selectedService?.id === service.id && styles.active,
              ]}
              onPress={() => {
                setSelectedService(service);
                setTime(null);
              }}
            >
              <View style={{ flex: 1 }}>
                <Text style={styles.serviceName}>{service.name}</Text>
                <Text style={styles.serviceTime}>{service.time}</Text>
              </View>
              <Text style={styles.price}>€{service.price}</Text>
            </TouchableOpacity>
          ))}

          {/* ===== زر صور حلاقتي ===== */}

          <TouchableOpacity
            style={styles.galleryButton}
            onPress={() => {
              setShowLangMenu(false);
              setScreen('gallery');
            }}
          >
            <Text style={styles.galleryButtonText}>🖼️ {t.gBtn}</Text>
          </TouchableOpacity>

          <View style={styles.line} />

          <Text style={styles.workingHours}>{t.workingHours}</Text>

          <TouchableOpacity
            style={styles.btn}
            onPress={() => {
              if (!selectedService) {
                Alert.alert('!', t.errS);
                return;
              }
              setScreen('booking');
            }}
          >
            <Text style={styles.btnText}>{t.btn1}</Text>
          </TouchableOpacity>
        </View>
      )}

      {/* ============ BOOKING ============ */}

      {screen === 'booking' && (
        <View style={styles.card}>
          <TouchableOpacity
            onPress={() => {
              resetBooking();
              setScreen('home');
            }}
          >
            <Text style={styles.back}>{t.back}</Text>
          </TouchableOpacity>

          <TextInput
            style={styles.input}
            placeholder={t.pName}
            placeholderTextColor="#666"
            value={name}
            onChangeText={setName}
            autoCapitalize="words"
          />

          <TextInput
            style={styles.input}
            placeholder={t.pPhone}
            placeholderTextColor="#666"
            keyboardType="phone-pad"
            value={phone}
            onChangeText={setPhone}
          />

          <View style={styles.line} />

          <Text style={styles.sectionTitleSmall}>{t.dLabel}</Text>

          <View style={styles.monthBox}>
            <Text style={styles.monthText}>
              {getMonthLabel(bookingRange)}
            </Text>
          </View>

          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.horizontalDaysLTR}
            onScroll={makeScrollHandler(setBookingRange)}
            scrollEventThrottle={16}
            onLayout={makeLayoutHandler(setBookingRange)}
          >
            {futureDates.map((date) => {
              const dateKey = dateToKey(date);
              const holiday = isHoliday(dateKey);
              const selected = selectedDateKey === dateKey;

              return (
                <TouchableOpacity
                  key={dateKey}
                  style={[
                    styles.dayBox,
                    styles.dayBoxLTR,
                    selected && styles.activeDayBox,
                    holiday && styles.holidayDayBox,
                  ]}
                  onPress={() => {
                    setSelectedDateKey(dateKey);
                    setTime(null);
                  }}
                >
                  <Text style={[styles.dayName, selected && styles.activeDayText]}>
                    {getShortDayName(date)}
                  </Text>
                  <Text style={[styles.dayNumber, selected && styles.activeDayText]}>
                    {date.getDate()}
                  </Text>
                  {holiday && <Text style={styles.holidayMini}>🚫</Text>}
                </TouchableOpacity>
              );
            })}
          </ScrollView>

          {selectedDateKey && isHoliday(selectedDateKey) && (
            <View style={styles.holidayMessageBox}>
              <Text style={styles.holidayMessageText}>🚫 {t.holidayNoBooking}</Text>
            </View>
          )}

          <Text style={styles.sectionTitleSmall}>{t.tLabel}</Text>

          {!selectedDateKey ? (
            <Text style={styles.warningText}>{t.selectDayFirst}</Text>
          ) : isHoliday(selectedDateKey) ? (
            <Text style={styles.warningText}>{t.holidayNoBooking}</Text>
          ) : availableTimes.length === 0 ? (
            <Text style={styles.warningText}>{t.noTimes}</Text>
          ) : (
            <ScrollView
              horizontal
              showsHorizontalScrollIndicator={false}
              contentContainerStyle={styles.horizontalTimesLTR}
            >
              {availableTimes.map((slotTime) => (
                <TouchableOpacity
                  key={slotTime}
                  style={[styles.timeBox, styles.timeBoxLTR, time === slotTime && styles.activeTimeBox]}
                  onPress={() => setTime(slotTime)}
                >
                  <Text
                    style={[styles.timeText, time === slotTime && styles.activeTimeText]}
                  >
                    {slotTime}
                  </Text>
                </TouchableOpacity>
              ))}
            </ScrollView>
          )}

          <TouchableOpacity
            style={[
              styles.btn,
              (!name.trim() ||
                !phone.trim() ||
                !selectedDateKey ||
                !time ||
                isHoliday(selectedDateKey)) &&
                styles.btnDisabled,
            ]}
            onPress={handleFinalBooking}
          >
            <Text style={styles.btnText}>{t.btn2}</Text>
          </TouchableOpacity>
        </View>
      )}

      {/* ============ GALLERY (للزبائن) ============ */}

      {screen === 'gallery' && (
        <View style={styles.card}>
          <TouchableOpacity onPress={() => setScreen('home')}>
            <Text style={styles.back}>{t.back}</Text>
          </TouchableOpacity>

          <Text style={styles.adminTitle}>{t.gBtn}</Text>

          {galleryPhotos.length === 0 ? (
            <Text style={styles.warningText}>{t.gEmpty}</Text>
          ) : (
            galleryPhotos.map((p) => (
              <Image
                key={p.id}
                source={{ uri: p.uri }}
                style={styles.galleryFull}
              />
            ))
          )}
        </View>
      )}

      {/* ============ ADMIN LOGIN ============ */}

      {screen === 'admin_login' && (
        <View style={styles.card}>
          <TouchableOpacity onPress={() => setScreen('home')}>
            <Text style={styles.back}>{t.back}</Text>
          </TouchableOpacity>

          <Text style={styles.adminTitle}>{t.loginTitle}</Text>

          <TextInput
            style={styles.input}
            placeholder={t.passwordPlaceholder}
            placeholderTextColor="#666"
            value={adminPassword}
            onChangeText={setAdminPassword}
            secureTextEntry
            keyboardType="number-pad"
          />

          <TouchableOpacity style={styles.btn} onPress={handleAdminLogin}>
            <Text style={styles.btnText}>{t.login}</Text>
          </TouchableOpacity>
        </View>
      )}

      {/* ============ ADMIN DASHBOARD ============ */}

      {screen === 'admin_dashboard' && (
        <View style={styles.card}>
          <View style={styles.dashboardHeader}>
            <Text style={styles.adminTitle}>{t.dashboard}</Text>

            <TouchableOpacity
              style={styles.logoutButton}
              onPress={() => setScreen('home')}
            >
              <Text style={styles.logoutText}>{t.logout}</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.line} />

          {/* العطلات والإجازات */}

          <Text style={styles.holidayAdminTitle}>📅 {t.selectHoliday}</Text>
          <Text style={styles.holidayAdminSub}>{t.holidayHint}</Text>

          <View style={styles.monthBox}>
            <Text style={styles.monthText}>{getMonthLabel(adminRange)}</Text>
          </View>

          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={styles.horizontalDaysLTR}
            onScroll={makeScrollHandler(setAdminRange)}
            scrollEventThrottle={16}
            onLayout={makeLayoutHandler(setAdminRange)}
          >
            {futureDates.map((date) => {
              const dateKey = dateToKey(date);
              const selected = isHoliday(dateKey);

              return (
                <TouchableOpacity
                  key={dateKey}
                  style={[styles.dayBox, styles.dayBoxLTR, selected && styles.activeHolidayBox]}
                  onPress={() => toggleHoliday(dateKey)}
                >
                  <Text
                    style={[styles.dayName, selected && styles.selectedHolidayText]}
                  >
                    {getShortDayName(date)}
                  </Text>
                  <Text
                    style={[styles.dayNumber, selected && styles.selectedHolidayText]}
                  >
                    {date.getDate()}
                  </Text>
                  {selected && <Text style={styles.doneText}>✓</Text>}
                </TouchableOpacity>
              );
            })}
          </ScrollView>

          <View style={styles.selectedHolidayContainer}>
            {holidayDates
              .filter((dateKey) =>
                futureDates.some((date) => dateToKey(date) === dateKey)
              )
              .sort()
              .map((dateKey) => (
                <View key={dateKey} style={styles.selectedHolidayRow}>
                  <Text style={styles.selectedHolidayDate}>
                    🚫 {formatAdminDate(dateKey)}
                  </Text>

                  <TouchableOpacity
                    style={styles.removeHolidayButton}
                    onPress={() => toggleHoliday(dateKey)}
                  >
                    <Text style={styles.removeHolidayText}>{t.remove}</Text>
                  </TouchableOpacity>
                </View>
              ))}
          </View>

          <View style={styles.line} />

          {/* دخول إلى صور عملي */}

          <TouchableOpacity
            style={styles.galleryButton}
            onPress={() => setScreen('admin_gallery')}
          >
            <Text style={styles.galleryButtonText}>🖼️ {t.gOpen}</Text>
          </TouchableOpacity>

          <View style={styles.line} />

          {/* الحجوزات */}

          {bookedSlots.length === 0 ? (
            <View style={styles.emptyBox}>
              <Text style={styles.emptyText}>{t.noBookings}</Text>
            </View>
          ) : (
            bookedSlots
              .slice()
              .sort((a, b) => {
                if (a.dateKey && b.dateKey) {
                  return (
                    a.dateKey.localeCompare(b.dateKey) ||
                    timeToMinutes(a.startTime) - timeToMinutes(b.startTime)
                  );
                }
                return (
                  (a.day || 0) - (b.day || 0) ||
                  timeToMinutes(a.startTime) - timeToMinutes(b.startTime)
                );
              })
              .map((item) => (
                <View key={item.id} style={styles.adminItem}>
                  <View style={{ flex: 1 }}>
                    <Text style={styles.clientName}>{item.clientName}</Text>

                    <Text style={styles.adminInfo}>
                      {t.phone}: {item.clientPhone}
                    </Text>

                    <Text style={styles.adminInfo}>
                      {t.service}: {item.serviceName}
                    </Text>

                    <Text style={styles.adminInfo}>
                      {t.day}:{' '}
                      {item.dateKey
                        ? formatAdminDate(item.dateKey)
                        : weekdayName(item.day)}
                    </Text>

                    <Text style={styles.adminInfo}>
                      {t.time}: {item.startTime}
                    </Text>

                    <Text style={styles.adminDuration}>
                      {t.duration}: {item.duration} min
                    </Text>
                  </View>

                  <TouchableOpacity
                    style={styles.deleteBtn}
                    onPress={() => deleteBooking(item.id)}
                  >
                    <Text style={styles.deleteText}>🗑️</Text>
                  </TouchableOpacity>
                </View>
              ))
          )}
        </View>
      )}

      {/* ============ ADMIN GALLERY ============ */}

      {screen === 'admin_gallery' && (
        <View style={styles.card}>
          <TouchableOpacity onPress={() => setScreen('admin_dashboard')}>
            <Text style={styles.back}>{t.back}</Text>
          </TouchableOpacity>

          <Text style={styles.adminTitle}>{t.gManage}</Text>

          <TouchableOpacity style={styles.btn} onPress={addPhoto}>
            <Text style={styles.btnText}>{t.gAdd}</Text>
          </TouchableOpacity>

          <View style={styles.line} />

          {galleryPhotos.length === 0 ? (
            <Text style={styles.warningText}>{t.gEmpty}</Text>
          ) : (
            galleryPhotos.map((p) => (
              <View key={p.id} style={styles.galleryRow}>
                <Image source={{ uri: p.uri }} style={styles.galleryThumb} />

                <View style={{ flex: 1, justifyContent: 'center' }}>
                  <TouchableOpacity
                    style={styles.logoutButton}
                    onPress={() => replacePhoto(p.id)}
                  >
                    <Text style={[styles.logoutText, { textAlign: 'center' }]}>
                      {t.gChange}
                    </Text>
                  </TouchableOpacity>

                  <TouchableOpacity
                    style={[styles.deleteBtn, { marginLeft: 0, marginTop: 10 }]}
                    onPress={() => deletePhoto(p.id)}
                  >
                    <Text style={[styles.deleteText, { textAlign: 'center' }]}>
                      🗑️
                    </Text>
                  </TouchableOpacity>
                </View>
              </View>
            ))
          )}
        </View>
      )}
    </ScrollView>
  );
}

